const EMPTY = () => ({ t: {}, img: {} });
/** k번째 장(0부터)의 채운 값 — 그 자리 레이아웃(f)이 바뀌었으면 빈 덮어쓰기 */
export function fillOf(id, k, f) {
  const x = FILLS[id] && FILLS[id][k];
  if (!x || (f && x.f !== f)) return EMPTY();
  const { f: _f, ...ov } = x;
  return { t: ov.t || {}, img: ov.img || {}, ...(ov.r ? { r: ov.r } : {}) };
}
